def reflect_retry(actor,evaluate,reflect,max_trials=3,capacity=2):
    if max_trials<0 or capacity<0:
        raise ValueError("negative budget")
    memory=[]
    for trial in range(1,max_trials+1):
        answer=actor(tuple(memory))
        if evaluate(answer):
            return answer,trial,memory
        memory.append(reflect(answer))
        memory=memory[-capacity:] if capacity else []
    return None,max_trials,memory

